<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class QuizAttempt extends Model { use HasFactory; protected $fillable=['quiz_id','student_id','attempt_no','status','started_at','expires_at','submitted_at','auto_submitted','question_order','option_order','objective_score','essay_score','total_score','graded_by','graded_at']; protected function casts():array{return['started_at'=>'datetime','expires_at'=>'datetime','submitted_at'=>'datetime','graded_at'=>'datetime','auto_submitted'=>'boolean','question_order'=>'array','option_order'=>'array','objective_score'=>'decimal:2','essay_score'=>'decimal:2','total_score'=>'decimal:2'];} public function quiz():BelongsTo{return $this->belongsTo(Quiz::class);} public function student():BelongsTo{return $this->belongsTo(User::class,'student_id');} public function answers():HasMany{return $this->hasMany(QuizAnswer::class);} public function grader():BelongsTo{return $this->belongsTo(User::class,'graded_by');} }
